for f in q1 q2; do echo "== $f" >> out.txt; curl -sS -X POST https://apis.justwatch.com/graphql -H "Content-Type: application/json" -A "Mozilla/5.0" --data @$f.json >> out.txt || true; echo >> out.txt; done
curl -sS "https://api.tvmaze.com/schedule/web?date=2026-11-21&country=DE" | python3 -c "import json,sys;d=json.load(sys.stdin);print('webDE',len(d),sorted(set((e.get('_embedded',{}).get('show',{}).get('webChannel') or {}).get('name','?') for e in d)))" >> out.txt || true
curl -sS "https://api.tvmaze.com/schedule?date=2026-11-21&country=DE" | python3 -c "import json,sys;d=json.load(sys.stdin);print('tvDE',len(d),sorted(set((e.get('show',{}).get('network') or {}).get('name','?') for e in d)))" >> out.txt || true
